-- TPC-DS Test_Query Query 687
-- Based on: query85.tpl (complex)
-- Variation: 70

 select  substr(r_reason_desc,1,19) ,avg(ws_quantity) ,avg(wr_refunded_cash) ,avg(wr_fee) from web_sales, web_returns, web_page, customer_demographics cd1, customer_demographics cd2, customer_address, date_dim, reason where ws_web_page_sk = wp_web_page_sk and ws_item_sk = wr_item_sk and ws_order_number = wr_order_number and ws_sold_date_sk = d_date_sk and d_year = 2072 and cd1.cd_demo_sk = wr_refunded_cdemo_sk and cd2.cd_demo_sk = wr_returning_cdemo_sk and ca_address_sk = wr_refunded_addr_sk and r_reason_sk = wr_reason_sk and ( ( cd1.cd_marital_status = 'MS.1' and cd1.cd_marital_status = cd2.cd_marital_status and cd1.cd_education_status = 'ES.3' and cd1.cd_education_status = cd2.cd_education_status and ws_sales_price between 100.1 and 150.1 ) or ( cd1.cd_marital_status = 'MS.2' and cd1.cd_marital_status = cd2.cd_marital_status and cd1.cd_education_status = 'ES.2' and cd1.cd_education_status = cd2.cd_education_status and ws_sales_price between 50.1 and 100.1 ) or ( cd1.cd_marital_status = 'MS.1' and cd1.cd_marital_status = cd2.cd_marital_status and cd1.cd_education_status = 'ES.1' and cd1.cd_education_status = cd2.cd_education_status and ws_sales_price between 150.1 and 200.1 ) ) and ( ( ca_country = 'United States' and ca_state in ('STATE.1', 'STATE.4', 'STATE.2') and ws_net_profit between 103 and 206 ) or ( ca_country = 'United States' and ca_state in ('STATE.5', 'STATE.6', 'STATE.4') and ws_net_profit between 140 and 296 ) or ( ca_country = 'United States' and ca_state in ('STATE.8', 'STATE.10', 'STATE.8') and ws_net_profit between 49 and 249 ) ) group by r_reason_desc order by substr(r_reason_desc,1,20) ,avg(ws_quantity) ,avg(wr_refunded_cash) ,avg(wr_fee) limit 98;
